import{_ as r,o as a,c as t,al as o}from"./chunks/framework.7vp1BMOE.js";const m=JSON.parse('{"title":"TeraRanger Rangefinders (Discontinued)","description":"","frontmatter":{},"headers":[],"relativePath":"en/sensor/teraranger.md","filePath":"en/sensor/teraranger.md"}'),n={name:"en/sensor/teraranger.md"};function i(s,e,l,d,c,u){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="teraranger-rangefinders-discontinued" tabindex="-1">TeraRanger Rangefinders (Discontinued) <a class="header-anchor" href="#teraranger-rangefinders-discontinued" aria-label="Permalink to &quot;TeraRanger Rangefinders (Discontinued)&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>TeraRanger Evo sensors were discontinued by Terabee in May 2024. Limited stock may still be available from third-party resellers such as <a href="https://tribotix.com/product/teraranger-evo-60m/" target="_blank" rel="noreferrer">Tribotix</a>.</p></div><p>TeraRanger provide a number of lightweight distance measurement sensor based on infrared Time-of-Flight (ToF) technology. They are typically faster and have greater range than sonar, and smaller and lighter than laser-based systems.</p><p>PX4 supports:</p><ul><li><a href="https://tribotix.com/product/teraranger-evo-60m/" target="_blank" rel="noreferrer">TeraRanger Evo 60m</a> (0.5 – 60 m)</li><li><a href="https://tribotix.com/product/teraranger-evo-600hz/" target="_blank" rel="noreferrer">TeraRanger Evo 600Hz</a> (0.75 - 8 m)</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PX4 also supports <em>TeraRanger One</em> (I2C adapter required). This has been discontinued.</p></div><h2 id="where-to-buy" tabindex="-1">Where to Buy <a class="header-anchor" href="#where-to-buy" aria-label="Permalink to &quot;Where to Buy&quot;">​</a></h2><ul><li>TBD</li></ul><h2 id="pinouts" tabindex="-1">Pinouts <a class="header-anchor" href="#pinouts" aria-label="Permalink to &quot;Pinouts&quot;">​</a></h2><h2 id="wiring" tabindex="-1">Wiring <a class="header-anchor" href="#wiring" aria-label="Permalink to &quot;Wiring&quot;">​</a></h2><p>All TeraRanger sensors must be connected via the I2C bus.</p><h2 id="software-configuration" tabindex="-1">Software Configuration <a class="header-anchor" href="#software-configuration" aria-label="Permalink to &quot;Software Configuration&quot;">​</a></h2><p>The sensors are enabled using the parameter <a href="./../advanced_config/parameter_reference#SENS_EN_TRANGER">SENS_EN_TRANGER</a> (you can set the type of sensor or that PX4 should auto-detect the type).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If using auto-detect for Evo sensors the minimum and maximum values for the range are set to the lowest and highest possible readings across the Evo family (currently 0.5 - 60 m). In order to use the correct max/min values the appropriate model of the Evo sensor should be set in the parameter (instead of using autodetect).</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The driver for this rangefinder is usually present in firmware. If missing, you would also need to add the driver (<code>distance_sensor/teraranger</code>) to the board configuration.</p></div><h2 id="further-information" tabindex="-1">Further Information <a class="header-anchor" href="#further-information" aria-label="Permalink to &quot;Further Information&quot;">​</a></h2><ul><li><a href="./../modules/modules_driver_distance_sensor#teraranger">Modules Reference: Distance Sensor (Driver) : teraranger</a></li></ul>',17)])])}const f=r(n,[["render",i]]);export{m as __pageData,f as default};
